// Reads the Helm repository index (docs/index.yaml) and turns it into the list
// of integrations the site renders.
//
// index.yaml is regenerated by `helm repo index` on every chart release, so it
// is always in step with the repo. Every card field the site needs is already
// there per chart entry: name, description, icon and annotations.type.
//
// Only the fields below are read, and `helm repo index` writes them in a fixed
// two-space-indented shape, so a tiny purpose-built reader is enough — the page
// needs no YAML library.

const TOP_LEVEL_KEY = /^([A-Za-z0-9_.-]+):/
const CHART_NAME = /^ {2}([A-Za-z0-9_.-]+):\s*$/
const ENTRY_START = /^ {2}- (.*)$/
const ENTRY_FIELD = /^ {4}([A-Za-z0-9_.-]+):\s*(.*)$/
const NESTED_FIELD = /^ {6}([A-Za-z0-9_.-]+):\s*(.*)$/
// `helm repo index` folds long values at ~80 columns and indents the rest, so a
// description regularly spills onto continuation lines that carry no key.
const CONTINUATION = /^ {6,}(?!- )(\S.*)$/
const BLOCK_SCALAR = /^[|>][-+]?$/

const WANTED_FIELDS = ["name", "version", "description", "icon"]

function unquote(value) {
  const trimmed = value.trim()
  const quoted = /^"(.*)"$/.exec(trimmed) || /^'(.*)'$/.exec(trimmed)
  return quoted ? quoted[1] : trimmed
}

// Applies a `key: value` pair to the entry.
//
// Returns what the following indented lines belong to:
//   { block: key }  a nested map such as `annotations:`
//   { folded: key } the rest of this value, wrapped onto continuation lines
//   {}              a complete value
function applyField(entry, line) {
  const pair = /^([A-Za-z0-9_.-]+):\s*(.*)$/.exec(line)
  if (!pair) return {}

  const [, key, rawValue] = pair
  const value = rawValue.trim()

  if (value === "") return { block: key }

  // `description: |-` and friends put the text on the following lines.
  if (BLOCK_SCALAR.test(value)) {
    if (WANTED_FIELDS.includes(key)) entry[key] = ""
    return { folded: key }
  }

  if (WANTED_FIELDS.includes(key)) {
    entry[key] = unquote(rawValue)
    return { folded: key }
  }

  return {}
}

// Joins a wrapped value back together. Both folded (`>`) and literal (`|`)
// blocks collapse to one line — cards are single-line text.
function appendContinuation(entry, key, text) {
  if (!WANTED_FIELDS.includes(key)) return

  const existing = entry[key]
  entry[key] = existing ? `${existing} ${text.trim()}` : text.trim()
}

// Parses index.yaml into { chartName: [entry, entry, ...] }, one entry per
// published version, each shaped { name, version, description, icon, annotations }.
export function parseHelmIndex(text) {
  const charts = new Map()

  let inEntries = false
  let versions = null
  let entry = null
  let nestedBlock = null
  let foldedKey = null

  for (const line of text.split(/\r?\n/)) {
    if (line.trim() === "" || line.trimStart().startsWith("#")) continue

    if (TOP_LEVEL_KEY.test(line)) {
      inEntries = line.startsWith("entries:")
      versions = null
      entry = null
      continue
    }

    if (!inEntries) continue

    const chartName = CHART_NAME.exec(line)
    if (chartName) {
      versions = []
      charts.set(chartName[1], versions)
      entry = null
      nestedBlock = null
      foldedKey = null
      continue
    }

    if (!versions) continue

    const entryStart = ENTRY_START.exec(line)
    if (entryStart) {
      entry = { annotations: {} }
      versions.push(entry)
      ;({ block: nestedBlock = null, folded: foldedKey = null } = applyField(entry, entryStart[1]))
      continue
    }

    if (!entry) continue

    const field = ENTRY_FIELD.exec(line)
    if (field) {
      ;({ block: nestedBlock = null, folded: foldedKey = null } = applyField(
        entry,
        `${field[1]}: ${field[2]}`
      ))
      continue
    }

    const nested = NESTED_FIELD.exec(line)
    if (nested && nestedBlock === "annotations") {
      entry.annotations[nested[1]] = unquote(nested[2])
      continue
    }

    const continuation = CONTINUATION.exec(line)
    if (continuation && foldedKey) {
      appendContinuation(entry, foldedKey, continuation[1])
    }
  }

  return charts
}

// Compares chart versions newest-first. Handles the `v` prefix this repo uses
// and falls back to a string compare for anything non-numeric.
export function compareVersionsDesc(a, b) {
  const parts = (version) =>
    String(version || "")
      .replace(/^v/i, "")
      .split(/[.\-+]/)

  const left = parts(a)
  const right = parts(b)

  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const l = left[i]
    const r = right[i]

    if (l === undefined) return 1
    if (r === undefined) return -1

    const ln = Number(l)
    const rn = Number(r)

    if (Number.isInteger(ln) && Number.isInteger(rn)) {
      if (ln !== rn) return rn - ln
      continue
    }

    if (l !== r) return l < r ? -1 : 1
  }

  return 0
}

// Newest published version of every chart in the index.
export function latestVersions(charts) {
  const latest = []

  charts.forEach((versions, name) => {
    const published = versions
      .filter((entry) => entry.version)
      .sort((a, b) => compareVersionsDesc(a.version, b.version))

    if (published.length === 0) return

    latest.push({ ...published[0], name: published[0].name || name })
  })

  return latest
}

// A chart shows up on the site when — and only when — it declares
// `annotations.type` in its Chart.yaml. Charts without it (building blocks such
// as `service` and `cron-job`, and the operator charts) stay off the grid.
export function integrationsFromIndex(text) {
  return latestVersions(parseHelmIndex(text))
    .filter((entry) => entry.annotations && entry.annotations.type)
    .map((entry) => ({
      id: entry.name,
      type: entry.annotations.type,
      version: entry.version,
      description: entry.description || "",
      icon: entry.icon || "",
    }))
}

export async function fetchIntegrations(url) {
  const response = await fetch(url)
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status}`)
  }

  return integrationsFromIndex(await response.text())
}
